package os.aios.core.events;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;

/** Durable business Event Hub. Delivery is at-least-once until explicitly acknowledged. */
public final class EventHub extends SQLiteOpenHelper{
 private static final long RETENTION=14L*86400000L;private static EventHub instance;
 public static synchronized void initialize(Context c){if(instance==null)instance=new EventHub(c.getApplicationContext());}
 public static synchronized void shutdown(){if(instance!=null){instance.close();instance=null;}}
 private static EventHub get(){if(instance==null)throw new IllegalStateException("Event Hub not initialized");return instance;}
 private EventHub(Context c){super(c,"aios_events.db",null,1);setWriteAheadLoggingEnabled(true);}
 public void onConfigure(SQLiteDatabase d){d.setForeignKeyConstraintsEnabled(true);}
 public void onCreate(SQLiteDatabase d){
  d.execSQL("CREATE TABLE events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,topic TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,payload TEXT NOT NULL,critical INTEGER NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL)");
  d.execSQL("CREATE INDEX events_topic_sequence ON events(topic,sequence)");
  d.execSQL("CREATE TABLE subscriptions(id TEXT PRIMARY KEY,owner TEXT NOT NULL,topics TEXT NOT NULL,mode TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,cursor INTEGER NOT NULL DEFAULT 0,acked INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)");
  d.execSQL("CREATE TABLE deliveries(subscription_id TEXT NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE,event_id TEXT NOT NULL,sequence INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','leased','acked','failed')),attempt INTEGER NOT NULL DEFAULT 0,generation INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL,PRIMARY KEY(subscription_id,event_id))");
 }
 public void onUpgrade(SQLiteDatabase d,int a,int b){throw new IllegalStateException("Unsupported Event Hub schema upgrade");}
 static void add(String topic,JSONObject data){try{publish(null,topic,data.optString("source_id",topic),data.optString("source_version",Long.toString(System.currentTimeMillis())),data,false);}catch(Exception e){android.util.Log.e("AIOSEvents","publish failed",e);}}
 public static synchronized JSONObject publish(String requested,String topic,String source,String version,JSONObject data,boolean critical)throws Exception{
  if(!allowed(topic))throw new IllegalArgumentException("Unsupported event topic: "+topic);if(data.toString().length()>32768)throw new IllegalArgumentException("Event payload exceeds 32 KiB; use URI/FD/Stream");
  String id=requested==null||requested.isEmpty()?os.aios.runtime.CoreContracts.stableId("event",topic,source,version):requested;EventHub s=get();SQLiteDatabase d=s.getWritableDatabase();long now=System.currentTimeMillis();d.beginTransaction();try{
   ContentValues v=new ContentValues();v.put("id",id);v.put("topic",topic);v.put("source_id",source);v.put("source_version",version);v.put("payload",data.toString());v.put("critical",critical?1:0);v.put("created_at",now);v.put("expires_at",now+RETENTION);long row=d.insertWithOnConflict("events",null,v,SQLiteDatabase.CONFLICT_IGNORE);JSONObject e=s.byId(d,id);
   if(row<0&&!(e.getString("type").equals(topic)&&e.getString("source_id").equals(source)&&e.getString("source_version").equals(version)&&e.getJSONObject("data").toString().equals(data.toString())))throw new IllegalArgumentException("event_id reused with different payload");
   s.deliver(d,e);s.prune(d,now);d.setTransactionSuccessful();return e.put("existing",row<0);
  }finally{d.endTransaction();}
 }
 public static synchronized JSONObject read(long after)throws Exception{EventHub s=get();SQLiteDatabase d=s.getReadableDatabase();long oldest=s.scalar(d,"MIN"),cursor=s.scalar(d,"MAX");return new JSONObject().put("events",s.events(d,"SELECT * FROM events WHERE sequence>? ORDER BY sequence LIMIT 256",Long.toString(after))).put("cursor",cursor).put("retention","14 days; pending critical facts retained").put("gap",oldest>0&&after<oldest-1);}
 public static synchronized JSONObject subscribe(JSONArray topics)throws Exception{return subscribe("tool",topics,"durable");}
 static synchronized JSONObject subscribe(String owner,JSONArray requested,String mode)throws Exception{
  if(requested==null||requested.length()<1||requested.length()>32)throw new IllegalArgumentException("topics must contain 1..32 entries");if(!Set.of("durable","ephemeral").contains(mode))throw new IllegalArgumentException("Invalid subscription mode");LinkedHashSet<String> topics=new LinkedHashSet<>();for(int i=0;i<requested.length();i++){String t=requested.getString(i);if(!allowed(t))throw new IllegalArgumentException("Unsupported event topic: "+t);topics.add(t);}
  EventHub s=get();SQLiteDatabase d=s.getWritableDatabase();String id=UUID.randomUUID().toString();long now=System.currentTimeMillis(),cursor=s.scalar(d,"MAX");ContentValues v=new ContentValues();v.put("id",id);v.put("owner",owner);v.put("topics",new JSONArray(topics).toString());v.put("mode",mode);v.put("cursor",cursor);v.put("acked",cursor);v.put("created_at",now);v.put("updated_at",now);d.insertOrThrow("subscriptions",null,v);return new JSONObject().put("subscription",id).put("owner",owner).put("topics",new JSONArray(topics)).put("cursor",cursor).put("delivery","at_least_once").put("lifetime",mode);
 }
 public static synchronized JSONObject poll(String id)throws Exception{
  EventHub s=get();SQLiteDatabase d=s.getWritableDatabase();JSONObject sub=s.sub(d,id);if(sub==null)return new JSONObject().put("state","not_found").put("subscription",id);long now=System.currentTimeMillis();d.beginTransaction();try{
   s.backfill(d,sub);JSONArray out=new JSONArray();try(Cursor c=d.rawQuery("SELECT e.* FROM deliveries x JOIN events e ON e.id=x.event_id WHERE x.subscription_id=? AND x.state IN ('pending','leased') AND (x.state='pending' OR x.lease_until<=?) ORDER BY x.sequence LIMIT 100",new String[]{id,Long.toString(now)})){while(c.moveToNext()){JSONObject e=s.event(c);out.put(e);d.execSQL("UPDATE deliveries SET state='leased',attempt=attempt+1,generation=generation+1,lease_until=?,updated_at=? WHERE subscription_id=? AND event_id=?",new Object[]{now+30000,now,id,e.getString("id")});}}
   long cursor=s.scalar(d,"MAX"),oldest=s.scalar(d,"MIN");d.execSQL("UPDATE subscriptions SET cursor=?,updated_at=? WHERE id=?",new Object[]{cursor,now,id});d.setTransactionSuccessful();return new JSONObject().put("subscription",id).put("events",out).put("cursor",cursor).put("acked",sub.getLong("acked")).put("gap",oldest>0&&sub.getLong("acked")<oldest-1).put("delivery","at_least_once; acknowledge after durable acceptance");
  }finally{d.endTransaction();}
 }
 public static synchronized JSONObject ack(String id,JSONArray ids)throws Exception{EventHub s=get();SQLiteDatabase d=s.getWritableDatabase();if(s.sub(d,id)==null)throw new IllegalArgumentException("Subscription not found");long max=0,now=System.currentTimeMillis();d.beginTransaction();try{for(int i=0;i<ids.length();i++){String event=ids.getString(i);try(Cursor c=d.rawQuery("SELECT sequence FROM deliveries WHERE subscription_id=? AND event_id=?",new String[]{id,event})){if(!c.moveToFirst())throw new IllegalArgumentException("Event was not delivered");max=Math.max(max,c.getLong(0));}d.execSQL("UPDATE deliveries SET state='acked',lease_until=0,updated_at=? WHERE subscription_id=? AND event_id=?",new Object[]{now,id,event});}d.execSQL("UPDATE subscriptions SET acked=MAX(acked,?),updated_at=? WHERE id=?",new Object[]{max,now,id});d.setTransactionSuccessful();return new JSONObject().put("subscription",id).put("acked",ids.length());}finally{d.endTransaction();}}
 public static synchronized JSONObject fail(String id,String event,String error)throws Exception{SQLiteDatabase d=get().getWritableDatabase();d.execSQL("UPDATE deliveries SET state=CASE WHEN attempt>=5 THEN 'failed' ELSE 'pending' END,lease_until=?,last_error=?,updated_at=? WHERE subscription_id=? AND event_id=?",new Object[]{System.currentTimeMillis()+60000,error.substring(0,Math.min(2048,error.length())),System.currentTimeMillis(),id,event});return new JSONObject().put("subscription",id).put("event_id",event).put("recorded",true);}
 public static synchronized JSONObject unsubscribe(String id)throws Exception{return new JSONObject().put("subscription",id).put("removed",get().getWritableDatabase().delete("subscriptions","id=?",new String[]{id})>0);}
 private void deliver(SQLiteDatabase d,JSONObject e)throws Exception{try(Cursor c=d.rawQuery("SELECT id,topics FROM subscriptions WHERE enabled=1",null)){while(c.moveToNext())if(matches(set(c.getString(1)),e.getString("type")))d.execSQL("INSERT OR IGNORE INTO deliveries(subscription_id,event_id,sequence,state,updated_at) VALUES(?,?,?,'pending',?)",new Object[]{c.getString(0),e.getString("id"),e.getLong("sequence"),System.currentTimeMillis()});}}
 private void backfill(SQLiteDatabase d,JSONObject sub)throws Exception{Set<String> topics=set(sub.getString("topics"));try(Cursor c=d.rawQuery("SELECT * FROM events WHERE sequence>? ORDER BY sequence",new String[]{Long.toString(sub.getLong("acked"))})){while(c.moveToNext()){JSONObject e=event(c);if(matches(topics,e.getString("type")))d.execSQL("INSERT OR IGNORE INTO deliveries(subscription_id,event_id,sequence,state,updated_at) VALUES(?,?,?,'pending',?)",new Object[]{sub.getString("id"),e.getString("id"),e.getLong("sequence"),System.currentTimeMillis()});}}}
 private JSONObject sub(SQLiteDatabase d,String id)throws Exception{try(Cursor c=d.rawQuery("SELECT * FROM subscriptions WHERE id=? AND enabled=1",new String[]{id})){if(!c.moveToFirst())return null;JSONObject o=new JSONObject();for(int i=0;i<c.getColumnCount();i++)o.put(c.getColumnName(i),c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));return o;}}
 private JSONObject byId(SQLiteDatabase d,String id)throws Exception{try(Cursor c=d.rawQuery("SELECT * FROM events WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalStateException("Event insert failed");return event(c);}}
 private JSONArray events(SQLiteDatabase d,String sql,String...args)throws Exception{JSONArray a=new JSONArray();try(Cursor c=d.rawQuery(sql,args)){while(c.moveToNext())a.put(event(c));}return a;}
 private JSONObject event(Cursor c)throws Exception{return new JSONObject().put("sequence",c.getLong(c.getColumnIndexOrThrow("sequence"))).put("id",c.getString(c.getColumnIndexOrThrow("id"))).put("time_ms",c.getLong(c.getColumnIndexOrThrow("created_at"))).put("type",c.getString(c.getColumnIndexOrThrow("topic"))).put("source_id",c.getString(c.getColumnIndexOrThrow("source_id"))).put("source_version",c.getString(c.getColumnIndexOrThrow("source_version"))).put("critical",c.getInt(c.getColumnIndexOrThrow("critical"))!=0).put("data",new JSONObject(c.getString(c.getColumnIndexOrThrow("payload"))));}
 private long scalar(SQLiteDatabase d,String fn){try(Cursor c=d.rawQuery("SELECT COALESCE("+fn+"(sequence),0) FROM events",null)){c.moveToFirst();return c.getLong(0);}}
 private void prune(SQLiteDatabase d,long now){d.execSQL("DELETE FROM events WHERE expires_at<? AND id NOT IN (SELECT event_id FROM deliveries WHERE state IN ('pending','leased'))",new Object[]{now});}
 private static Set<String> set(String value)throws Exception{JSONArray a=new JSONArray(value);Set<String>s=new LinkedHashSet<>();for(int i=0;i<a.length();i++)s.add(a.getString(i));return s;}
 static boolean matches(Set<String> topics,String type){for(String t:topics)if(t.endsWith(".")?type.startsWith(t):type.equals(t))return true;return false;}
 static boolean allowed(String t){return t!=null&&t.length()<=160&&(t.startsWith("android.intent.action.")||t.startsWith("notification.")||t.startsWith("sensor.")||t.startsWith("location.")||t.startsWith("workspace.")||t.startsWith("context.")||t.startsWith("dream.")||t.startsWith("automation.")||t.startsWith("runtime."));}
}
